unsafe extern "C" fn m_far_move_actor(actor: *mut c_void, location: *const FVector) {
    if actor.is_null() || location.is_null() {
        return;
    }
    let location = unsafe { *location };
    with(|s| {
        lg(
            s,
            format!(
                "far {:08x} {:08x} {:08x} 0 0\n",
                bits(location.x),
                bits(location.y),
                bits(location.z)
            ),
        );
        unsafe { (*actor.cast::<AActor>()).location = location };
    });
}
