#[repr(C)]
struct MockTrailerState {
    owner: *mut c_void,
    mesh: *mut c_void,
    pre_pivot: [f32; 3],
    mass: f32,
    draw_type: i32,
    anim_bone: i32,
    flags: u32,
}

unsafe extern "C" fn m_trailer_state(actor: *mut c_void, out: *mut c_void) {
    if actor.is_null() || out.is_null() {
        return;
    }
    let owner = unsafe { (*actor.cast::<AActor>()).owner };
    let (pre_pivot, mass, draw_type, anim_bone, flags) = with(|s| {
        (
            s.trailer_prepivot,
            s.trailer_mass,
            s.trailer_draw_type,
            s.trailer_anim_bone,
            s.trailer_flags,
        )
    });
    unsafe {
        out.cast::<MockTrailerState>()
            .write_unaligned(MockTrailerState {
                owner: owner.cast(),
                mesh: if anim_bone != 0 {
                    std::ptr::dangling_mut::<c_void>()
                } else {
                    null_mut()
                },
                pre_pivot,
                mass,
                draw_type,
                anim_bone,
                flags,
            });
    }
}

unsafe extern "C" fn m_mesh_bone_coords(
    _mesh: *mut c_void,
    _owner: *mut c_void,
    _bone: i32,
    out: *mut c_void,
) {
    if out.is_null() {
        return;
    }
    let v = with(|s| s.trailer_bone_coords);
    let coords = hp2_abi::FCoords {
        origin: FVector {
            x: v[0],
            y: v[1],
            z: v[2],
        },
        x_axis: FVector {
            x: v[3],
            y: v[4],
            z: v[5],
        },
        y_axis: FVector {
            x: v[6],
            y: v[7],
            z: v[8],
        },
        z_axis: FVector {
            x: v[9],
            y: v[10],
            z: v[11],
        },
    };
    unsafe { out.cast::<hp2_abi::FCoords>().write_unaligned(coords) };
}

